const KNOWLEDGE_BASE = "O STFS: STFS to zespół inżynierów, projektantów i specjalistów AI. Wdrażamy automatyzacje, strony internetowe i wsparcie marketingu oparte na danych. Pracujemy zarówno ze startupami budującymi pierwszy produkt, jak i z firmami przenoszącymi procesy na AI.\n\nUsługa — Automatyzacje AI: Łączymy narzędzia firmy i modele językowe w procesy, które same kwalifikują leady, odpowiadają na zapytania i aktualizują dane bez udziału zespołu. Obejmuje: kwalifikację i scoring leadów, automatyczne odpowiedzi i follow-up, integracje CRM/e-mail/kalendarz.\n\nUsługa — Strony internetowe: Projektujemy i wdrażamy strony, które startują szybko, konwertują ruch i nie zabierają zespołowi tygodni na wdrażanie zmian. Obejmuje: landing page pod kampanie, panel do samodzielnej edycji treści, wdrożenie w 2 do 4 tygodni.\n\nUsługa — Wsparcie marketingu: Automatyzujemy raportowanie kampanii, generujemy treści z pomocą AI i optymalizujemy lejek sprzedażowy na podstawie danych. Obejmuje: automatyczne raporty kampanii, generowanie treści z AI, optymalizację lejków sprzedażowych.\n\nUsługa — Startupy dla firm: Pomagamy firmom uruchamiać nowe przedsięwzięcia z AI od pierwszej wersji produktu — od walidacji pomysłu po pierwszych klientów. Obejmuje: walidację pomysłu i MVP w tygodnie, AI wbudowane od pierwszej wersji, wsparcie w pozyskaniu klientów.\n\nProces współpracy: 1) Konsultacja — darmowa, 30-minutowa rozmowa ustalająca cele i zakres. 2) Diagnoza i plan — audyt strony/procesów/danych. 3) Wdrożenie — budowa strony/automatyzacji z cotygodniowym podglądem postępu. 4) Skalowanie — po starcie mierzymy dane i dokładamy kolejne automatyzacje AI.\n\nModele współpracy: Projekt jednorazowy (konkretny zakres, jeden cel, wycena stała po konsultacji) — dla jednego celu. Stała opieka (comiesięczne wsparcie rozwoju: nowe automatyzacje, optymalizacje, marketing w jednym abonamencie) — najczęściej wybierane. Partnerstwo wzrostowe (długoterminowa współpraca z elastycznym zakresem) — dla startupów i firm skalujących się.\n\nKonsultacja: Darmowa konsultacja trwa 30 minut i jest bezpłatna. Można ją zarezerwować online przez panel na stronie (kalendarz Cal.com), dostępne terminy to zwykle 12:00-18:00, z minimum 2-dniowym wyprzedzeniem. W konsultacji: analiza obecnej strony/procesów/kampanii, konkretne rekomendacje nawet bez dalszej współpracy, wstępna wycena i realny harmonogram.\n\nKontakt: e-mail kontakt@stfs.pl, telefon +48 887 326 773. Najlepszym pierwszym krokiem jest umówienie darmowej konsultacji przez stronę.\n\nTechnologie, których używa STFS: GPT-4o, Claude, LangChain, n8n, Make, Zapier, Next.js, Supabase, bazy wektorowe.";

const systemPrompt = "Jesteś asystentem AI na stronie STFS (AI studio dla biznesu). Odpowiadaj wyłącznie na podstawie poniższej wiedzy o STFS. Bądź zwięzły, konkretny, po polsku, przyjazny. Jeśli nie znasz odpowiedzi z tej wiedzy, powiedz to wprost i zaproponuj umówienie darmowej konsultacji przez stronę. Nigdy nie wymyślaj cen ani faktów, których nie ma w kontekście.\n\nWiedza o STFS:\n" + KNOWLEDGE_BASE;

const CLIENT_KEY = "stfs-site-widget-2026";
const headerKey = ($json.headers && $json.headers["x-stfs-client"]) || "";
const authorized = headerKey === CLIENT_KEY;

const MAX_QUESTION_LENGTH = 500;
let question = ($json.body && $json.body.question ? $json.body.question : ($json.question || "")).toString().slice(0, MAX_QUESTION_LENGTH);
if (!authorized) {
  question = "Przywitaj się krótko i zaproponuj kontakt przez formularz konsultacji.";
}

return [{
  json: {
    ...$json,
    question,
    body: {
      model: "gpt-4o-mini",
      max_tokens: 400,
      messages: [
        { role: "system", content: systemPrompt },
        { role: "user", content: question },
      ],
    },
  },
}];
